class Solution{
public:
    int numJewelsInStones(string jewels,string stones){
        bool a[128]={};
        for(char c:jewels) a[(unsigned char)c]=true;
        int count=0;
        for(char c:stones) if(a[(unsigned char)c]) count++;
        return count;
    }
};

