class Solution{
    public int numJewelsInStones(String jewels,String stones){
        boolean[] a=new boolean[128];
        for(char c:jewels.toCharArray()) a[c]=true;
        int count=0;
        for(char c:stones.toCharArray()) if(a[c]) count++;
        return count;
    }
}

